const body = $input.first().json.body || $input.first().json;
const studioId = body.studio_id;
const email = body.email || body.instructor_email;

if (!studioId) throw new Error('studio_id is required');

const supaUrl = 'https://kidgcrqxrfcbsaeguwop.supabase.co';
const key = $vars.FCA_SUPABASE_SERVICE_KEY;
const h = { apikey: key, Authorization: 'Bearer ' + key };

// Fetch studio data
const sRes = await fetch(supaUrl + '/rest/v1/studio_accounts?id=eq.' + studioId + '&select=studio_name,brand_voice,brand_color,brand_color_secondary,brand_font,logo_url,studio_type', { headers: h });
const studios = await sRes.json();
const studio = (Array.isArray(studios) && studios[0]) || {};

// Fetch instructor bio from clients
let instructor = { name: body.instructor_name || 'Instructor', bio: null, specialties: null };
if (email) {
  const cRes = await fetch(supaUrl + '/rest/v1/clients?email=eq.' + encodeURIComponent(email) + '&studio_id=eq.' + studioId + '&select=id,bio,specialties', { headers: h });
  const clients = await cRes.json();
  if (Array.isArray(clients) && clients[0]) {
    instructor.bio = clients[0].bio || null;
    instructor.specialties = clients[0].specialties || null;
    instructor.client_id = clients[0].id;
  }
}

return [{ json: {
  studio_id: studioId,
  studio_name: studio.studio_name || 'Fitness Studio',
  brand_voice: studio.brand_voice || '',
  brand_color: studio.brand_color || '#1a1a1a',
  brand_color_secondary: studio.brand_color_secondary || '#ffffff',
  brand_font: studio.brand_font || 'Montserrat',
  logo_url: studio.logo_url || '',
  studio_type: studio.studio_type || 'general_fitness',
  instructor_name: instructor.name,
  instructor_bio: instructor.bio,
  instructor_specialties: instructor.specialties,
  instructor_client_id: instructor.client_id || null,
  topic: body.topic || null,
  email: email
} }];

const claudeRes = $input.first().json;
const studio = $('Fetch Studio & Instructor').first().json;

// Parse Claude response
let responseText = '';
if (claudeRes.content && Array.isArray(claudeRes.content)) {
  responseText = claudeRes.content[0]?.text || '';
} else if (typeof claudeRes === 'string') {
  responseText = claudeRes;
}

// Extract JSON array
let slides;
try {
  const match = responseText.match(/\[\s*\{[\s\S]*\}\s*\]/);
  slides = JSON.parse(match ? match[0] : responseText);
} catch (e) {
  throw new Error('Failed to parse carousel JSON from Claude: ' + e.message);
}

if (!Array.isArray(slides) || slides.length !== 5) {
  throw new Error('Expected 5 slides, got ' + (slides ? slides.length : 0));
}

// Build Creatomate render payloads
const bc = studio.brand_color;
const bc2 = studio.brand_color_secondary;
const bf = studio.brand_font;
const logo = studio.logo_url;

const renders = slides.map((slide, i) => {
  const isFirst = i === 0;
  const isLast = i === 4;
  const elements = [];

  // Background
  elements.push({ type: 'shape', x: '50%', y: '50%', width: '100%', height: '100%', fill_color: bc });

  // Logo on slides 1 and 5
  if ((isFirst || isLast) && logo) {
    elements.push({ type: 'image', source: logo, x: '50%', y: '15%', width: '25%', fit: 'contain' });
  }

  // Headline
  elements.push({
    type: 'text', text: slide.headline || '', x: '50%', y: (isFirst || isLast) && logo ? '45%' : '35%',
    width: '85%', font_family: bf, font_weight: '800', font_size: '9 vmin',
    fill_color: bc2, x_alignment: '50%', y_alignment: '50%', line_height: '120%'
  });

  // Body
  elements.push({
    type: 'text', text: slide.body || '', x: '50%', y: (isFirst || isLast) && logo ? '65%' : '60%',
    width: '80%', font_family: bf, font_weight: '400', font_size: '5.5 vmin',
    fill_color: bc2, x_alignment: '50%', y_alignment: '50%', line_height: '140%'
  });

  // CTA button on slide 5
  if (isLast && slide.cta) {
    elements.push({ type: 'shape', x: '50%', y: '82%', width: '65%', height: '9%', fill_color: bc2, border_radius: '50' });
    elements.push({
      type: 'text', text: slide.cta, x: '50%', y: '82%', width: '60%',
      font_family: bf, font_weight: '700', font_size: '5 vmin',
      fill_color: bc, x_alignment: '50%', y_alignment: '50%'
    });
  }

  // Slide counter dot indicators at bottom
  const dotY = '93%';
  for (let d = 0; d < 5; d++) {
    elements.push({
      type: 'shape', x: (38 + d * 6) + '%', y: dotY,
      width: '2.5%', height: '2.5%', border_radius: '50',
      fill_color: d === i ? bc2 : (bc2 + '44')
    });
  }

  return {
    output_format: 'jpg',
    width: 1080, height: 1080,
    elements: elements
  };
});

return [{ json: { slides, renders, studio } }];

const renders = $input.first().json;
const prev = $('Parse Slides & Build Renders').first().json;

// Creatomate returns array of render objects
const renderArray = Array.isArray(renders) ? renders : [renders];
const ids = renderArray.map(r => r.id);

return [{ json: { render_ids: ids, slides: prev.slides, studio: prev.studio, render_count: ids.length } }];

const prev = .first().json;
const ids = prev.render_ids;

const results = [];
let allDone = true;

for (const id of ids) {
  const res = await fetch("https://api.creatomate.com/v2/renders/" + id, {
    headers: { Authorization: "Bearer " + .CREATOMATE_API_KEY }
  });
  const r = await res.json();
  results.push({ id: r.id, status: r.status, url: r.url || null });
  if (r.status !== "succeeded" && r.status !== "failed") allDone = false;
}

return [{ json: { ...prev, render_results: results, all_done: allDone } }];

const prev = $input.first().json;
const slides = prev.slides;
const results = prev.render_results;
const studio = prev.studio;

// Merge image URLs into slides
const enrichedSlides = slides.map((slide, i) => ({
  ...slide,
  image_url: results[i]?.url || null
}));

// Posting tip (feed_post timing for carousels)
const tipMatrix = {
  yoga_pilates: 'Best for your audience: Tue/Thu 7\u20139am or Sun evening 6\u20138pm',
  hiit_crossfit: 'Best for your audience: Mon/Wed/Fri 6\u20138am or 6\u20138pm',
  dance_barre: 'Best for your audience: Tue/Thu 12\u20132pm or 7\u20139pm',
  martial_arts: 'Best for your audience: Tue/Thu 4\u20136pm or 7\u20139pm',
  general_fitness: 'Best for most fitness audiences: Mon/Wed/Fri 12pm or 7pm'
};
const postingTip = tipMatrix[studio.studio_type] || tipMatrix.general_fitness;

// Save to fitness_content
const supaUrl = 'https://kidgcrqxrfcbsaeguwop.supabase.co';
const key = $vars.FCA_SUPABASE_SERVICE_KEY;
try {
  await fetch(supaUrl + '/rest/v1/fitness_content', {
    method: 'POST',
    headers: {
      apikey: key, Authorization: 'Bearer ' + key,
      'Content-Type': 'application/json', Prefer: 'return=minimal'
    },
    body: JSON.stringify({
      content_type: 'carousel',
      platform: 'instagram',
      content_data: { slides: enrichedSlides },
      studio_id: studio.studio_id
    })
  });
} catch (e) { /* non-critical */ }

return [{ json: {
  success: true,
  carousel: enrichedSlides,
  postingTip: postingTip,
  studioType: studio.studio_type,
  studio_name: studio.studio_name
} }];
